import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { vendorService } from '../../services/vendorService';
import LoadingSpinner from '../common/LoadingSpinner';
import { getErrorMessage } from '../../utils/helpers';
import { SUCCESS_MESSAGES } from '../../utils/constants';

const ApplicationForm = () => {
  const [profile, setProfile] = useState(null);
  const [loading, setLoading] = useState(false);
  const [profileLoading, setProfileLoading] = useState(true);
  const [error, setError] = useState('');
  const [message, setMessage] = useState('');
  const navigate = useNavigate();

  useEffect(() => {
    loadProfile();
  }, []);

  const loadProfile = async () => {
    try {
      setProfileLoading(true);
      const response = await vendorService.getProfile();
      setProfile(response.data);
    } catch (error) {
      setError('Please complete your profile before creating an application.');
    } finally {
      setProfileLoading(false);
    }
  };

  const handleCreateApplication = async () => {
    if (!profile || !profile.profileComplete) {
      setError('Please complete your profile first');
      return;
    }

    setLoading(true);
    setError('');
    setMessage('');

    try {
      const response = await vendorService.createApplication();
      setMessage('Application created successfully!');
      
      // Redirect to application status page
      setTimeout(() => {
        navigate('/application-status');
      }, 2000);
    } catch (error) {
      setError(getErrorMessage(error));
    } finally {
      setLoading(false);
    }
  };

  if (profileLoading) {
    return <LoadingSpinner message="Loading your profile..." />;
  }

  if (!profile) {
    return (
      <div className="application-form-page">
        <div className="container">
          <div className="error-container">
            <div className="error-message">
              <h2>Profile Required</h2>
              <p>You need to complete your vendor profile before creating an application.</p>
              <button 
                onClick={() => navigate('/vendor-profile')} 
                className="btn btn-primary"
              >
                Complete Profile
              </button>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="application-form-page">
      <div className="container">
        <div className="page-header">
          <h1>Create License Application</h1>
          <p>Submit your food truck license application</p>
        </div>

        {message && <div className="success-message">{message}</div>}
        {error && <div className="error-message">{error}</div>}

        <div className="application-preview">
          <h3>Application Preview</h3>
          <p>Your application will include the following information from your profile:</p>
          
          <div className="profile-summary">
            <div className="summary-section">
              <h4>Business Information</h4>
              <div className="info-grid">
                <div className="info-item">
                  <label>Business Name:</label>
                  <span>{profile.name}</span>
                </div>
                <div className="info-item">
                  <label>Phone Number:</label>
                  <span>{profile.phoneNumber}</span>
                </div>
                <div className="info-item">
                  <label>Business Address:</label>
                  <span>{profile.businessAddress}</span>
                </div>
              </div>
            </div>

            <div className="summary-section">
              <h4>Food Service Information</h4>
              <div className="info-grid">
                <div className="info-item">
                  <label>Cuisine Specialties:</label>
                  <span>{profile.cuisineSpecialties}</span>
                </div>
                <div className="info-item">
                  <label>Operating Region:</label>
                  <span>{profile.operatingRegion}</span>
                </div>
                {profile.menuHighlights && (
                  <div className="info-item">
                    <label>Menu Highlights:</label>
                    <span>{profile.menuHighlights}</span>
                  </div>
                )}
              </div>
            </div>
          </div>

          <div className="application-requirements">
            <h4>Application Process</h4>
            <ol className="requirements-list">
              <li>Your application will be created with the above information</li>
              <li>Once created, you can submit it for review</li>
              <li>Admin will review your application</li>
              <li>If approved, an inspection may be scheduled</li>
              <li>Upon successful inspection, your license will be issued</li>
            </ol>
          </div>

          <div className="form-actions">
            <button 
              onClick={() => navigate('/vendor-dashboard')}
              className="btn btn-outline"
            >
              Cancel
            </button>
            
            <button 
              onClick={() => navigate('/vendor-profile')}
              className="btn btn-secondary"
            >
              Edit Profile
            </button>
            
            <button 
              onClick={handleCreateApplication}
              className="btn btn-primary"
              disabled={loading}
            >
              {loading ? 'Creating Application...' : 'Create Application'}
            </button>
          </div>
        </div>

        {loading && <LoadingSpinner message="Creating your application..." />}

        <div className="help-section">
          <h4>Need Help?</h4>
          <p>If you have questions about the application process, please contact our support team or check the documentation.</p>
        </div>
      </div>
    </div>
  );
};

export default ApplicationForm;
